"""
Advanced Function Toolkit
A collection of utility functions demonstrating advanced Python function concepts.
"""

import time
from functools import wraps, reduce, partial
from typing import Any, Callable, List, Dict, Union

# 1. Decorator Utilities

def timed(unit='seconds'):
    """Decorator that times function execution."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            result = func(*args, **kwargs)
            end = time.perf_counter()

            duration = end - start
            if unit == 'ms':
                duration *= 1000
            elif unit == 'us':
                duration *= 1000000

            print(f"{func.__name__} took {duration:.2f} {unit}")
            return result
        return wrapper
    return decorator

def cache(maxsize=128, ttl=None):
    """Decorator that caches function results."""
    def decorator(func):
        cache_dict = {}
        cache_times = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = str(args) + str(sorted(kwargs.items()))

            # Check cache expiration
            if ttl and key in cache_times:
                if time.time() - cache_times[key] > ttl:
                    del cache_dict[key]
                    del cache_times[key]

            if key not in cache_dict:
                # Enforce maxsize
                if len(cache_dict) >= maxsize:
                    # Remove oldest entry
                    oldest_key = next(iter(cache_dict))
                    del cache_dict[oldest_key]
                    if ttl:
                        del cache_times[oldest_key]

                cache_dict[key] = func(*args, **kwargs)
                if ttl:
                    cache_times[key] = time.time()

            return cache_dict[key]
        return wrapper
    return decorator

def retry(max_attempts=3, delay=1, backoff=2):
    """Decorator that retries failed function calls."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            current_delay = delay

            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        raise e

                    print(f"Attempt {attempts} failed: {e}. Retrying in {current_delay}s...")
                    time.sleep(current_delay)
                    current_delay *= backoff

            return None
        return wrapper
    return decorator

def validate_types(*types):
    """Decorator that validates function argument types."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i, (arg, expected_type) in enumerate(zip(args, types)):
                if not isinstance(arg, expected_type):
                    raise TypeError(f"Argument {i} must be {expected_type.__name__}, got {type(arg).__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

# 2. Functional Programming Utilities

def compose(*functions):
    """Compose multiple functions into a single function."""
    def composed(*args, **kwargs):
        result = functions[-1](*args, **kwargs)
        for func in reversed(functions[:-1]):
            result = func(result)
        return result
    return composed

def curry(func):
    """Convert a function to curried form."""
    @wraps(func)
    def curried(*args, **kwargs):
        if len(args) + len(kwargs) >= func.__code__.co_argcount:
            return func(*args, **kwargs)
        return lambda *args2, **kwargs2: curried(*(args + args2), **{**kwargs, **kwargs2})
    return curried

def memoize(key_func=None):
    """Memoize function results with custom key function."""
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            if key_func:
                key = key_func(*args, **kwargs)
            else:
                key = str(args) + str(sorted(kwargs.items()))

            if key not in cache:
                cache[key] = func(*args, **kwargs)

            return cache[key]
        return wrapper
    return decorator

# 3. Data Processing Utilities

def pipeline(*processors):
    """Create a data processing pipeline."""
    def process(data):
        result = data
        for processor in processors:
            result = processor(result)
        return result
    return process

def batch_process(batch_size=100):
    """Process data in batches."""
    def decorator(func):
        @wraps(func)
        def wrapper(data):
            results = []
            for i in range(0, len(data), batch_size):
                batch = data[i:i + batch_size]
                results.extend(func(batch))
            return results
        return wrapper
    return decorator

def aggregate_data(aggregator, data):
    """Aggregate data using various reduction operations."""
    return reduce(aggregator, data)

# 4. Configuration & Validation Utilities

class FunctionBuilder:
    """Build configured functions dynamically."""
    def __init__(self):
        self.filters = []
        self.transformations = []

    def where(self, **conditions):
        """Add filtering conditions."""
        def filter_func(item):
            return all(item.get(k) == v for k, v in conditions.items())
        self.filters.append(filter_func)
        return self

    def transform(self, transformation):
        """Add transformation function."""
        self.transformations.append(transformation)
        return self

    def build(self):
        """Build the final processing function."""
        def processor(data):
            # Apply filters
            for filter_func in self.filters:
                data = filter(filter_func, data)
            data = list(data)

            # Apply transformations
            for transform in self.transformations:
                data = list(map(transform, data))

            return data
        return processor

def create_validator(*validations):
    """Create a validation function from multiple validation rules."""
    def validator(data):
        errors = []
        for validation in validations:
            try:
                validation(data)
            except ValueError as e:
                errors.append(str(e))

        if errors:
            raise ValueError("; ".join(errors))
        return True
    return validator

# Test the toolkit
if __name__ == "__main__":
    # Test timed decorator
    @timed(unit='ms')
    def test_function():
        time.sleep(0.1)
        return "Done"

    print(test_function())

    # Test pipeline
    process = pipeline(
        lambda x: x * 2,
        lambda x: x + 10,
        lambda x: f"Result: {x}"
    )
    print(process(5))

    # Test FunctionBuilder
    builder = FunctionBuilder().where(status='active').transform(lambda x: x['name'].upper())
    processor = builder.build()
    data = [
        {'name': 'alice', 'status': 'active'},
        {'name': 'bob', 'status': 'inactive'},
        {'name': 'charlie', 'status': 'active'}
    ]
    print(processor(data))
